package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.resources.ResourceLocation; import net.neoforged.neoforge.client.extensions.common.IClientFluidTypeExtensions; import net.neoforged.neoforge.fluids.FluidType; import java.util.function.Consumer;
public final class OilFluidType extends FluidType {private final int tint;public OilFluidType(Properties p,int tint){super(p);this.tint=tint;}@Override public void initializeClient(Consumer<IClientFluidTypeExtensions> c){c.accept(new IClientFluidTypeExtensions(){private final ResourceLocation STILL=ResourceLocation.withDefaultNamespace("block/water_still"),FLOW=ResourceLocation.withDefaultNamespace("block/water_flow");@Override public ResourceLocation getStillTexture(){return STILL;}@Override public ResourceLocation getFlowingTexture(){return FLOW;}@Override public int getTintColor(){return tint;}});}}
